const r = (name, category, en, it, officialUrl = "", extra = {}) => ({
  name, category, en, it, officialUrl, ...extra,
});

const weekly = (entries) => Object.fromEntries(entries.map(([day, open, close]) => [day, { open, close }]));
const weekdays = (open, close) => weekly(["mon", "tue", "wed", "thu", "fri"].map((day) => [day, open, close]));
const market = (name, en, it, officialUrl, hours, extra = {}) => r(name, "SHOPPING", en, it, officialUrl,
  { accessType: "VARIABLE", visitMinutes: 45, hours, market: true, ...extra });

